  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Castagneur-(Guerrier).html&quot; title=&quot;Castagneur&quot;&gt;Castagneur&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Du-Marteau-(Guerrier).html&quot; title=&quot;Champion du marteau&quot;&gt;Champion du marteau&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combattant-&#192;-Deux-Armes-(Guerrier).html&quot; title=&quot;Combattant &#224; deux armes&quot;&gt;Combattant &#224; deux armes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combattant-&#192;-Deux-Mains-(Guerrier).html&quot; title=&quot;Combattant &#224; deux mains&quot;&gt;Combattant &#224; deux mains&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combattant-De-La-Main-Libre-(Guerrier).html&quot; title=&quot;Combattant de la main libre&quot;&gt;Combattant de la main libre&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combattant-D&#233;loyal-(Guerrier).html&quot; title=&quot;Combattant d&#233;loyal&quot;&gt;Combattant d&#233;loyal&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Orque-(Race).html&quot; title=&quot;Les orques&quot;&gt;Orque&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Corsaire-(Guerrier).html&quot; title=&quot;Corsaire&quot;&gt;Corsaire&lt;/a&gt; (PMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Molthuni-(Guerrier).html&quot; title=&quot;D&#233;fenseur molthuni&quot;&gt;D&#233;fenseur molthuni&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Du-Savoir-(Guerrier).html&quot; title=&quot;D&#233;fenseur du savoir&quot;&gt;D&#233;fenseur du savoir&lt;/a&gt; (RSE)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dragon-(Guerrier).html&quot; title=&quot;Dragon&quot;&gt;Dragon&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Embusqueur-Des-Airs-(Guerrier).html&quot; title=&quot;Embusqueur des airs&quot;&gt;Embusqueur des airs&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Strix-(Race).html&quot; title=&quot;Les strix&quot;&gt;Strix&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Frappe-Tonnerre-(Guerrier).html&quot; title=&quot;Frappe-tonnerre&quot;&gt;Frappe-tonnerre&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Occulte-(Guerrier).html&quot; title=&quot;Gardien occulte&quot;&gt;Gardien occulte&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gladiateur-(Guerrier).html&quot; title=&quot;Gladiateur&quot;&gt;Gladiateur&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-D&#233;sarm&#233;-(Guerrier).html&quot; title=&quot;Guerrier d&#233;sarm&#233;&quot;&gt;Guerrier d&#233;sarm&#233;&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-Mobile-(Guerrier).html&quot; title=&quot;Guerrier mobile&quot;&gt;Guerrier mobile&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-Mutag&#233;nique-(Guerrier).html&quot; title=&quot;Guerrier mutag&#233;nique&quot;&gt;Guerrier mutag&#233;nique&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-Nomade-Au-Style-Libre-(Guerrier).html&quot; title=&quot;Guerrier nomade au style libre&quot;&gt;Guerrier nomade au style libre&lt;/a&gt; (&lt;i&gt;WMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-Sauvage-(Guerrier).html&quot; title=&quot;Guerrier sauvage&quot;&gt;Guerrier sauvage&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-Sensitif-(Guerrier).html&quot; title=&quot;Guerrier sensitif&quot;&gt;Guerrier sensitif&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invincible-(Guerrier).html&quot; title=&quot;Invincible&quot;&gt;Invincible&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Maitre-Darmes-(Guerrier).html&quot; title=&quot;Ma&#238;tre d&amp;#39;armes&quot;&gt;Ma&#238;tre d&#39;armes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Dhast-(Guerrier).html&quot; title=&quot;Ma&#238;tre d&amp;#39;hast&quot;&gt;Ma&#238;tre d&#39;hast&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Armures-(Guerrier).html&quot; title=&quot;Ma&#238;tre des armures&quot;&gt;Ma&#238;tre des armures&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Reliques-(Guerrier).html&quot; title=&quot;Ma&#238;tre des reliques&quot;&gt;Ma&#238;tre des reliques&lt;/a&gt; (&lt;i&gt;WMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Du-Bouclier-(Guerrier).html&quot; title=&quot;Ma&#238;tre du bouclier&quot;&gt;Ma&#238;tre du bouclier&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Martial-(Guerrier).html&quot; title=&quot;Ma&#238;tre martial&quot;&gt;Ma&#238;tre martial&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Malotru-(Guerrier).html&quot; title=&quot;Malotru&quot;&gt;Malotru&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Monteur-De-B&#234;tes-(Guerrier).html&quot; title=&quot;Monteur de b&#234;tes&quot;&gt;Monteur de b&#234;tes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phalange-(Guerrier).html&quot; title=&quot;Phalange&quot;&gt;Phalange&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sp&#233;cialiste-Du-Pavois-(Guerrier).html&quot; title=&quot;Sp&#233;cialiste du pavois&quot;&gt;Sp&#233;cialiste du pavois&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tacticien-(Guerrier).html&quot; title=&quot;Tacticien&quot;&gt;Tacticien&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tireur-Embusqu&#233;-Des-Cavernes-(Guerrier).html&quot; title=&quot;Tireur embusqu&#233; des cavernes&quot;&gt;Tireur embusqu&#233; des cavernes&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Drow-(Race).html&quot; title=&quot;Les drows&quot;&gt;Drow&lt;/a&gt;) (MR)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Au combat, la plupart des guerriers respectent un certain code de l’honneur. Certains pensent qu’il ne faut pas s’acharner sur un ennemi au sol ou qu’il faut r&#233;server les coups d&#233;loyaux aux situations d&#233;sesp&#233;r&#233;es. Le malotru ne s’embarrasse pas de ces principes. Il se bat pour gagner et tout ce qui peut lui donner un avantage est bon &#224; prendre. Aucune manoeuvre n’est trop fourbe si elle permet d’obtenir la victoire.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes et armures&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_et_armures_0&quot; href=&quot;#Armes_et_armures_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le malotru n’est pas form&#233; au port des &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Intermediaires.html&quot; title=&quot;armure interm&#233;diaire&quot;&gt;armures interm&#233;diaires&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Lourdes.html&quot; title=&quot;armure lourde&quot;&gt;lourdes&lt;/a&gt; ni au maniement du pavois.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Comp&#233;tences&lt;a class=&quot;headeranchor&quot; id=&quot;Comp&#233;tences_1&quot; href=&quot;#Comp&#233;tences_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici les comp&#233;tences de classe du malotru : &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt;. &lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Manoeuvres d&#233;loyales (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Manoeuvres_d&#233;loyales_Ext_2&quot; href=&quot;#Manoeuvres_d&#233;loyales_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 2, le malotru apprend comme tromper et d&#233;concerter ses adversaires. Il gagne un bonus de +1 aux tests de manoeuvre de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Desarmement.html&quot; title=&quot;d&#233;sarmement&quot;&gt;d&#233;sarmement&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Salecoup.html&quot; title=&quot;sale coup&quot;&gt;sale coup&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Subtilisation.html&quot; title=&quot;subtilisation&quot;&gt;subtilisation&lt;/a&gt;. Il gagne aussi un bonus de +1 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; quand quelqu’un tente d’effectuer ces manoeuvres contre lui. Ces bonus augmentent de 1 tous les quatre niveaux apr&#232;s le 2 (avec un maximum de +5 au niveau 18). Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#COURAGE&quot; title=&quot;Le guerrier&quot;&gt;courage&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Surprise&lt;a class=&quot;headeranchor&quot; id=&quot;Surprise_3&quot; href=&quot;#Surprise_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 3, le malotru obtient le don &lt;a class=&quot;pagelink&quot; href=&quot;Surprise.html&quot; title=&quot;Surprise&quot;&gt;Surprise&lt;/a&gt;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#ENTRAINEMENTAUXARMURES&quot; title=&quot;Le guerrier&quot;&gt;entra&#238;nement aux armures&lt;/a&gt; 1.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Tu vas payer (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Tu_vas_payer_Ext_4&quot; href=&quot;#Tu_vas_payer_Ext_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 5, le malotru gagne un bonus de +1 aux jets d’attaque et de d&#233;g&#226;ts contre toutes les cr&#233;atures qui l’ont attaqu&#233; depuis le d&#233;but du dernier tour. Ce bonus augmente de +1 tous les quatre niveaux apr&#232;s le 5 (avec un maximum de +4 au niveau 17). Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#ENTRAINEMENTAUXARMES&quot; title=&quot;Le guerrier&quot;&gt;entra&#238;nement aux armes&lt;/a&gt; 1, 3 et 4.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Surprise mortelle (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Surprise_mortelle_Ext_5&quot; href=&quot;#Surprise_mortelle_Ext_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 7, quand un malotru utilise une arme ou une attaque &#224; mains nues et touche un adversaire priv&#233; de son bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;], il peut tenter une manoeuvre de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Salecoup.html&quot; title=&quot;sale coup&quot;&gt;sale coup&lt;/a&gt;, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt; qui fait partie de son attaque. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#ENTRAINEMENTAUXARMURES&quot; title=&quot;Le guerrier&quot;&gt;entra&#238;nement aux armures&lt;/a&gt; 2.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pied de chaise aiguis&#233; (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Pied_de_chaise_aiguis&#233;_Ext_6&quot; href=&quot;#Pied_de_chaise_aiguis&#233;_Ext_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 9, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;, le malotru peut changer le type de d&#233;g&#226;ts d’une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armesimprovisees.html&quot; title=&quot;arme improvis&#233;e&quot;&gt;arme improvis&#233;e&lt;/a&gt; pour la rendre contondante, tranchante ou perforante. De plus, il menace une zone de critique de 19–20/&#215;2 avec cette arme. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#ENTRAINEMENTAUXARMES&quot; title=&quot;Le guerrier&quot;&gt;entra&#238;nement aux armes&lt;/a&gt; 2.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;L&#226;che combattant (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;L&#226;che_combattant_Ext_7&quot; href=&quot;#L&#226;che_combattant_Ext_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 11, quand le malotru se bat sur la d&#233;fensive ou qu’il utilise l’&lt;a class=&quot;pagelink&quot; href=&quot;Expertise-Du-Combat.html&quot; title=&quot;Expertise du combat&quot;&gt;Expertise du combat&lt;/a&gt; ou la &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Defensetotale.html&quot; title=&quot;d&#233;fense totale&quot;&gt;d&#233;fense totale&lt;/a&gt;, il ne peut plus &#234;tre pris en &lt;a class=&quot;pagelink&quot; href=&quot;Modificateurs-De-Combat#Priseentenaille.html&quot; title=&quot;prise en tenaille&quot;&gt;tenaille&lt;/a&gt;, sauf par un &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html&quot; title=&quot;Le roublard&quot;&gt;roublard&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;Ninja.html&quot; title=&quot;Le ninja&quot;&gt;ninja&lt;/a&gt; qui poss&#232;de au moins quatre niveaux de plus que son niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;guerrier&lt;/a&gt;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#ENTRAINEMENTAUXARMURES&quot; title=&quot;Le guerrier&quot;&gt;entra&#238;nement aux armures&lt;/a&gt; 3.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Farce de groupe (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Farce_de_groupe_Ext_8&quot; href=&quot;#Farce_de_groupe_Ext_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 13, le malotru peut, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, faire une manoeuvre de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Salecoup.html&quot; title=&quot;sale coup&quot;&gt;sale coup&lt;/a&gt; contre deux adversaires adjacents &#224; sa port&#233;e. Il fait un test distinct pour chacun mais doit utiliser le m&#234;me tour contre les deux. Au niveau 17, il peut faire cela lors d’une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; pour affecter un nombre d’adversaires &#233;gal &#224; 2 + son &#233;ventuel bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#ENTRAINEMENTAUXARMES&quot; title=&quot;Le guerrier&quot;&gt;entra&#238;nement aux armes&lt;/a&gt; 3 et 4.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Coup en tra&#238;tre (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Coup_en_tra&#238;tre_Ext_9&quot; href=&quot;#Coup_en_tra&#238;tre_Ext_9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 15, quand le malotru confirme un &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;coup critique&lt;/a&gt;, il peut tenter une manoeuvre de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Salecoup.html&quot; title=&quot;sale coup&quot;&gt;sale coup&lt;/a&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;. Elle fait partie de l’attaque. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#ENTRAINEMENTAUXARMURES&quot; title=&quot;Le guerrier&quot;&gt;entra&#238;nement aux armures&lt;/a&gt; 4.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Tu vas payer cher (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Tu_vas_payer_cher_Ext_10&quot; href=&quot;#Tu_vas_payer_cher_Ext_10&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 20, si le malotru menace de faire un &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;coup critique&lt;/a&gt; contre un adversaire qui l’a attaqu&#233; depuis le d&#233;but de son dernier tour, il confirme automatiquement le critique. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#MAITRISEDESARMES&quot; title=&quot;Le guerrier&quot;&gt;ma&#238;trise des armes&lt;/a&gt;.
